// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller1, address caller2, uint256 amount1, uint256 amount2) public {
        vm.assume(caller1 != address(0) && caller2 != address(0) && caller1 != caller2);
        vm.assume(amount1 <= address(this).balance / 2);
        vm.assume(amount2 <= address(this).balance / 2);

        // Initial total = contract balance + all user balances
        uint256 initialTotal = address(c).balance + c.balances(caller1) + c.balances(caller2);

        // Deposit from caller1
        vm.deal(caller1, amount1);
        vm.prank(caller1);
        (bool ok1, ) = address(c).call{value: amount1}("");
        require(ok1);

        // Deposit from caller2
        vm.deal(caller2, amount2);
        vm.prank(caller2);
        (bool ok2, ) = address(c).call{value: amount2}("");
        require(ok2);

        // Withdraw from caller1
        vm.prank(caller1);
        c.withdraw();

        // Calculate final total
        uint256 finalTotal = address(c).balance + c.balances(caller1) + c.balances(caller2);

        // Invariant: total supply remains constant
        assertTrue(initialTotal == finalTotal);
    }
}

