pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint256 public totalDeposited;

    function setUp() public { 
        c = new C(); 
        totalDeposited = 0;
    }

    function testFuzz_property(address sender, uint256 depositAmount, uint256 withdrawAmount) public {
        // Bound deposit and withdraw amounts to avoid overflow
        depositAmount = bound(depositAmount, 0, 1e18);
        withdrawAmount = bound(withdrawAmount, 0, 1e18);

        // Ensure sender has enough Ether
        vm.assume(sender != address(0));
        vm.deal(sender, depositAmount + withdrawAmount);

        // Deposit
        vm.prank(sender);
        (bool depositSuccess,) = address(c).call{value: depositAmount}("");
        require(depositSuccess, "Deposit failed");
        totalDeposited += depositAmount;

        // Withdraw only up to sender's balance
        uint256 senderBalance = c.balances(sender);
        if (withdrawAmount > senderBalance) {
            withdrawAmount = senderBalance;
        }

        // Attempt withdraw
        vm.prank(sender);
        (bool withdrawSuccess,) = address(c).call(abi.encodeWithSignature("withdraw()"));
        // If withdraw succeeded, set balances to zero for sender
        // If it reverted (due to failed send), balances remain unchanged but contract might have lost gas
        // We only test when withdraw does NOT revert, because the bug affects only non-reverting case

        // Measure state after withdraw
        uint256 contractBalance = address(c).balance;
        // Sum all balances — but we cannot iterate over all addresses, so we only check sender's balance
        // Instead, we use a simpler invariant: after successful withdraw, sender's balance is zero
        if (withdrawSuccess) {
            uint256 newSenderBalance = c.balances(sender);
            assertTrue(newSenderBalance == 0, "After successful withdraw, sender's balance should be zero");
        }
    }
}

