pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 depositAmount, uint256 withdrawAmount) public {
        // Bound deposit and withdraw amounts to avoid overflow and ensure meaningful test
        depositAmount = bound(depositAmount, 1, 100 ether);
        withdrawAmount = bound(withdrawAmount, 1, depositAmount);

        // Ensure caller is not the zero address
        vm.assume(caller != address(0));

        // Fund the caller with enough Ether
        vm.deal(caller, depositAmount);

        // Deposit Ether into the contract via fallback
        vm.prank(caller);
        (bool depositSuccess,) = address(c).call{value: depositAmount}("");
        require(depositSuccess);

        // Record initial caller balance
        uint256 initialCallerBalance = c.balances(caller);

        // Attempt withdraw of the full balance (or less if not enough)
        vm.prank(caller);
        uint256 valueToWithdraw = withdrawAmount;
        // To ensure we withdraw exactly the balance, set valueToWithdraw to initialCallerBalance
        // But we use the fuzzed withdrawAmount to test different scenarios
        // The contract withdraws the entire balance, not a specified amount
        // So we adjust: if withdrawAmount < initialCallerBalance, we still withdraw full balance
        // We'll just call withdraw and check the condition

        // Try to withdraw
        vm.prank(caller);
        (bool withdrawSuccess,) = address(c).call(abi.encodeWithSignature("withdraw()"));

        // After withdraw, check the caller's balance
        uint256 finalCallerBalance = c.balances(caller);

        // The property: if withdraw succeeded, final balance must be 0; if it failed, final balance stays unchanged
        if (withdrawSuccess) {
            assertTrue(finalCallerBalance == 0, "after successful withdraw, balance should be 0");
        } else {
            assertTrue(finalCallerBalance == initialCallerBalance, "after failed withdraw, balance should remain unchanged");
        }
    }
}

