// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address sender, uint256 depositAmount, address withdrawer, uint256 withdrawAmount) public {
        // Ensure withdrawer has some balance before withdraw
        vm.assume(withdrawer != address(0) && sender != address(0));
        vm.assume(depositAmount > 0 && depositAmount <= type(uint256).max / 2);
        vm.assume(withdrawAmount > 0 && withdrawAmount <= type(uint256).max / 2);

        // Deposit to sender via fallback
        vm.deal(address(this), depositAmount);
        vm.prank(sender);
        (bool successDeposit, ) = address(c).call{value: depositAmount}("");
        require(successDeposit, "deposit failed");

        // Deposit to withdrawer via fallback
        vm.deal(address(this), withdrawAmount);
        vm.prank(withdrawer);
        (bool successDeposit2, ) = address(c).call{value: withdrawAmount}("");
        require(successDeposit2, "deposit2 failed");

        // Record sum before withdraw
        uint256 sumBefore = c.balances(sender) + c.balances(withdrawer);
        uint256 contractBalanceBefore = address(c).balance;

        // Now a random user (neither sender nor withdrawer) calls withdraw() for himself? Actually, let's make sender withdraw to avoid revert
        vm.prank(sender);
        c.withdraw();

        // After withdraw, total of all balances should be less than or equal to contract ether balance + previous sum
        uint256 sumAfter = c.balances(sender) + c.balances(withdrawer);
        uint256 contractBalanceAfter = address(c).balance;

        // The invariant: sum of balances never exceeds contract ether + initial sum before this step
        assertTrue(sumAfter <= contractBalanceAfter + sumBefore);
    }
}
